[
  {
    "question": "Which statement most accurately distinguishes a DBMS from a traditional file‑based system?",
    "options": {
      "A": "A DBMS stores data in a single flat file, while a file‑based system uses multiple files.",
      "B": "A DBMS provides data independence, query processing, and concurrency control that file‑based systems lack.",
      "C": "A DBMS requires manual indexing, whereas a file‑based system automatically creates indexes.",
      "D": "A DBMS eliminates the need for backup and recovery mechanisms, unlike file‑based systems."
    },
    "correct_answer": "B",
    "explanation": "The syllabus notes that a DBMS “preserves correctness and performance under concurrent access” and offers abstraction layers, which are not provided by simple file‑based approaches.",
    "difficulty": "Medium"
  },
  {
    "question": "In the three‑level ANSI/SPARC architecture, which level defines the external view seen by individual users?",
    "options": {
      "A": "Internal level",
      "B": "Conceptual level",
      "C": "External level",
      "D": "Physical level"
    },
    "correct_answer": "C",
    "explanation": "The external level stores user‑specific schemas (views), separating each user’s perspective from the underlying logical and physical structures, as described in the fundamentals of data abstraction.",
    "difficulty": "Medium"
  },
  {
    "question": "Which term specifically denotes the collection of definitions that describe the logical structure of a database?",
    "options": {
      "A": "Instance",
      "B": "Metadata",
      "C": "Schema",
      "D": "Catalog"
    },
    "correct_answer": "C",
    "explanation": "The syllabus lists “schema” among the retrieval keywords for database fundamentals, defining it as the logical description of the database’s organization.",
    "difficulty": "Medium"
  },
  {
    "question": "What is the primary benefit of logical data independence in a DBMS?",
    "options": {
      "A": "Application programs need not be rewritten when the logical schema changes.",
      "B": "Physical storage devices can be replaced without altering the DBMS software.",
      "C": "Query execution time is automatically reduced after schema modifications.",
      "D": "Referential integrity constraints are enforced without user intervention."
    },
    "correct_answer": "A",
    "explanation": "Logical data independence means that changes to the logical schema (e.g., adding a table or attribute) do not affect external schemas or application code, a core concept highlighted in the fundamentals material.",
    "difficulty": "Medium"
  },
  {
    "question": "Which of the following is NOT a function of the database catalog (system catalog)?",
    "options": {
      "A": "Storing definitions of tables, columns, and constraints",
      "B": "Recording statistical information used by the query optimizer",
      "C": "Holding the actual user data rows of application tables",
      "D": "Maintaining metadata about indexes and views"
    },
    "correct_answer": "C",
    "explanation": "The catalog contains metadata about the database structure, not the user data itself; user data resides in the database tables, not in the system catalog.",
    "difficulty": "Medium"
  }
]
